package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd
 */
public class MathUtils_gcd_TriageGen5Test {







    @Test
    public void testGcdWithPowersOfTwo() {
        // Tests the 'k' loop (B1) and the 'k == 31' overflow check
        assertEquals(4, MathUtils.gcd(4, 8));
        assertEquals(2, MathUtils.gcd(2, 10));
        assertEquals(8, MathUtils.gcd(8, 64));

        // Test the k=31 overflow (though practically hard to hit with int inputs 
        // without violating u*v != 0, we aim for high k)
        // If u = -2^30 and v = -2^30, k will reach 30.
        // To trigger k=31, we would need u and v to be 0, but that is caught by the first if.
        // However, we can test a high k.
        assertEquals(1024, MathUtils.gcd(1024, 2048));
    }








}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd
 */
public class MathUtils_gcd_TriageGen5Test {









    @Test
    public void testGcdOddAndEven() {
        // Tests B2/B3: t initialization logic
        // Case: u is odd, v is even -> t = v
        assertEquals(2, MathUtils.gcd(3, 2)); // u=3, v=2 -> u becomes -3, v becomes -2. k=0. u is odd. t = -2.

        // Case: u is even, v is odd -> t = -(u/2)
        assertEquals(1, MathUtils.gcd(2, 3)); 
    }






}

